-- Add an immutable archive of finalized renderers/assets; never replaces document snapshots or master data.
CREATE TABLE document_format_archives (
 version integer PRIMARY KEY CHECK(version>0), fingerprint text UNIQUE NOT NULL,
 payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER document_format_archives_immutable BEFORE UPDATE OR DELETE ON document_format_archives FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
INSERT INTO document_format_archives(version,fingerprint,payload) VALUES(1,'c5edf5cc722a7592a6998be1349171c50071c341fc2949f8fe287240f311d72f', $format${"label":"Finalized document formats - owner preservation instruction 14 October 2026","files":{"server/commercial/report.ts":"import {orderCustomerScopeLines} from './customer-scope.js';\nimport { quotationDisplayRows } from \"./quotation-rows.js\";\nimport { displayUnit } from \"../boq/unit.js\";\nimport {\n  drawReportLogo,\n  drawReportFooter,\n  reportBottomMargin,\n} from \"../reports/branding.js\";\nimport { Decimal } from \"decimal.js\";\nimport { jsPDF } from \"jspdf\";\nimport { autoTable } from \"jspdf-autotable\";\nimport type { QuotationSnapshot } from \"./engine.js\";\nconst text = (v: string) =>\n  v\n    .replaceAll(\"×\", \"x\")\n    .replace(/[–—]/g, \"-\")\n    .replace(/[^\\n\\x20-\\x7e\\xa0-\\xff]/g, \"\");\nconst money = (v: string) =>\n  new Intl.NumberFormat(\"en-PK\", {\n    minimumFractionDigits: 2,\n    maximumFractionDigits: 2,\n  }).format(Number(v));\nfunction appendQuotation(\n  pdf: jsPDF,\n  s: QuotationSnapshot,\n  number?: string,\n  label?: string,\n) {\n  // Promotional presentation only. The immutable net/tax basis remains unchanged for review and IPO/PT.\n  if(s.standardDiscountStrategy && s.standardDiscountStrategy.version !== 'PZ-STANDARD-DISCOUNT-2'){\n    const D=Decimal;\n    const included=s.footer.some(r=>r.label===\"Total\");\n    const groups=s.standardDiscountStrategy.groups.map(g=>({...g,amount:new D(g.beforeTax).mul(included?new D(g.taxRate).div(100).add(1):1).toDecimalPlaces(2,Decimal.ROUND_HALF_UP)}));\n    const allowance=groups.reduce((sum,g)=>sum.add(g.amount),new D(0));\n    const lines=s.lines.map(l=>({...l}));\n    for(const group of groups){\n      const members=lines.filter(l=>l.group===group.group&&l.amount!==undefined);\n      if(members.some(l=>l.standardAllowanceBeforeTax!==undefined)){\n        let assigned=new D(0);\n        members.forEach((row,index)=>{const extra=index===members.length-1?group.amount.sub(assigned):new D(row.standardAllowanceBeforeTax??\"0\").mul(included?new D(group.taxRate).div(100).add(1):1).toDecimalPlaces(2,Decimal.ROUND_HALF_UP);assigned=assigned.add(extra);row.amount=new D(row.amount!).add(extra).toFixed(2);});\n      }else if(members[0])members[0].amount=new D(members[0].amount!).add(group.amount).toFixed(2);\n    }\n    const footer=s.footer.map(r=>({...r}));\n    const total=footer.find(r=>r.label===(included?\"Total\":\"Subtotal Before Tax\"));\n    if(total)total.amount=new D(total.amount).add(allowance).toFixed(2);\n    const index=footer.findIndex(r=>r.label===\"Special Discount\");\n    footer.splice(included?index:1,0,{label:\"Management-approved discount\",amount:allowance.toFixed(2)});\n    s={...s,lines,footer};\n  }\n  if(s.discountAuthorization){\n    const allowance=new Decimal(s.discountAuthorization.preapprovedBeforeTax),requested=new Decimal(s.discountAuthorization.requestedBeforeTax);\n    const approved=Decimal.min(allowance,requested),special=Decimal.max(0,requested.sub(allowance));\n    const footer=s.footer.flatMap(row=>row.label==='Special Discount'?[{label:'Approved Discount',amount:approved.toFixed(2)},{label:'Management Special Discount',amount:special.toFixed(2)}]:[row]);\n    s={...s,footer};\n  }\n  const margin = 14;\n  pdf.setProperties({\n    title: number ?? \"Quotation preview\",\n    author: \"Power Zone Engineering & Services (Pvt) Limited\",\n    subject: s.subject,\n  });\n  pdf.setFont(\"helvetica\", \"bold\");\n  pdf.setFontSize(17);\n  pdf.setTextColor(57, 50, 83);\n  drawReportLogo(pdf);\n  pdf.setFontSize(9);\n  pdf.setFont(\"helvetica\", \"normal\");\n  if (label) {\n    pdf.setFontSize(7);\n    pdf.text(text(label), 196, 20, { align: \"right\" });\n  }\n\n  pdf.setTextColor(40, 40, 45);\n  pdf.setFontSize(12);\n  pdf.text(number ? \"QUOTATION\" : \"DRAFT QUOTATION - NOT SAVED\", margin, 37);\n  pdf.setFontSize(9);\n  pdf.text(\"POWER ZONE ENGINEERING & SERVICES (PVT) LIMITED\", margin, 42);\n  autoTable(pdf, {\n    startY: 46,\n    margin: { left: margin, right: margin },\n    theme: \"plain\",\n    styles: { fontSize: 8, cellPadding: 0.6, textColor: [40, 40, 45] },\n    columnStyles: { 0: { cellWidth: 102 }, 1: { cellWidth: 80 } },\n    body: [\n      [\n        text(`Customer: ${s.customer.name}`),\n        text(`Quoted date: ${s.input.quotedDate}`),\n      ],\n      [\n        text(`Contact person: ${s.customer.contactPerson ?? \"\"}`),\n        text(`Proposed by: ${s.input.proposedBy}`),\n      ],\n      [\n        text(`Contact number: ${s.customer.phone ?? \"\"}`),\n        text(`Validity: ${s.input.validity}`),\n      ],\n      [\n        text(`Site: ${s.siteName} (${s.siteCode})`),\n        text(`Solution ID: ${s.solutionId}`),\n      ],\n      [\n        text(`BOQ: ${s.boqNumber}`),\n        text(`Quotation No.: ${number ?? \"DRAFT\"}`),\n      ],\n    ],\n  });\n  let y = (pdf as any).lastAutoTable.finalY + 4;\n  pdf.text(text(s.subject), margin, y);\n  y += 5;\n  const amounts = s.presentation !== \"No Breakup\";\n  const body = quotationDisplayRows(\"customerScopeVersion\" in s && s.customerScopeVersion === 1 ? orderCustomerScopeLines(s.lines, s.presentation) : s.lines).map((r, i) => {\n    const cells: any[] = [\n      String(i + 1),\n      text(r.description),\n      displayUnit(r.unit,r.qty),\n      new Intl.NumberFormat(\"en-PK\", { maximumFractionDigits: 4 }).format(\n        Number(r.qty),\n      ),\n    ];\n    if (amounts && r.amount)\n      cells.push({ content: money(r.amount), rowSpan: r.span });\n    return cells;\n  });\n  autoTable(pdf, {\n    startY: y,\n    margin: { left: margin, right: margin, bottom: reportBottomMargin },\n    head: [\n      [\n        \"No.\",\n        \"Product / Service Description\",\n        \"UOM\",\n        \"Qty\",\n        ...(amounts ? [\"Amount (PKR)\"] : []),\n      ],\n    ],\n    body,\n    theme: \"grid\",\n    styles: {\n      fontSize: 7,\n      cellPadding: 0.5,\n      overflow: \"linebreak\",\n      lineColor: [230, 230, 238],\n      lineWidth: 0.2,\n    },\n    headStyles: { fillColor: [65, 54, 104] },\n    columnStyles: {\n      0: { cellWidth: 7, halign: \"center\" },\n      1: { cellWidth: amounts ? 129 : 151 },\n      2: { cellWidth: 14, halign: \"center\", valign: \"middle\" },\n      3: { cellWidth: 10, halign: \"center\" },\n      ...(amounts\n        ? { 4: { cellWidth: 22, halign: \"right\", valign: \"middle\" } }\n        : {}),\n    },\n    didParseCell(data) {\n      if (data.column.index === 2) {\n        data.cell.styles.halign = \"center\";\n        data.cell.styles.valign = \"middle\";\n      }\n    },\n    rowPageBreak: \"avoid\",\n  });\n  y = (pdf as any).lastAutoTable.finalY + 3;\n  autoTable(pdf, {\n    startY: y,\n    margin: { left: 96, right: margin, bottom: reportBottomMargin },\n    theme: \"plain\",\n    pageBreak: \"avoid\",\n    tableWidth: 100,\n    body: s.footer.map((r) => [r.label, money(r.amount)]),\n    styles: { fontSize: 8, cellPadding: 1 },\n    columnStyles: {\n      0: { cellWidth: 78, halign: \"right\" },\n      1: { cellWidth: 22, halign: \"right\" },\n    },\n    didParseCell(data) {\n      if (data.row.index === s.footer.length - 1) {\n        data.cell.styles.fontStyle = \"bold\";\n        data.cell.styles.fillColor = false;\n      }\n    },\n  });\n  y = (pdf as any).lastAutoTable.finalY + 3;\n  autoTable(pdf, {\n    startY: y,\n    margin: { left: margin, right: margin, bottom: reportBottomMargin },\n    theme: \"plain\",\n    body: [\n      [{ content: \"NOTES\", styles: { fontStyle: \"bold\" } }],\n      ...s.notes.map((r, i) => [text(`${i + 1}. ${r}`)]),\n      [{ content: \"TERMS AND CONDITIONS\", styles: { fontStyle: \"bold\" } }],\n      ...s.terms.map((r, i) => [text(`${i + 1}. ${r}`)]),\n    ],\n    styles: { fontSize: 7, cellPadding: 0.3, overflow: \"linebreak\" },\n    rowPageBreak: \"avoid\",\n  });\n}\nexport function buildQuotationPdf(s: QuotationSnapshot, number?: string) {\n  const pdf = new jsPDF({ unit: \"mm\", format: \"a4\", compress: true });\n  appendQuotation(pdf, s, number);\n  drawReportFooter(pdf, text(number ?? \"Draft quotation\"));\n  return Buffer.from(pdf.output(\"arraybuffer\"));\n}\nexport function buildQuotationComparisonPdf(\n  variants: { snapshot: QuotationSnapshot; label: string }[],\n  sourceNumber: string,\n) {\n  const pdf = new jsPDF({ unit: \"mm\", format: \"a4\", compress: true });\n  variants.forEach((v, i) => {\n    if (i) pdf.addPage();\n    appendQuotation(\n      pdf,\n      v.snapshot,\n      sourceNumber,\n      `REVIEW PREVIEW ${i + 1}/6 - ${v.label}`,\n    );\n  });\n  pdf.setProperties({\n    title: `${sourceNumber} - six quotation formats`,\n    subject: \"Comparison previews only; saved quotation unchanged.\",\n  });\n  drawReportFooter(pdf, text(`${sourceNumber} - format review only`));\n  return Buffer.from(pdf.output(\"arraybuffer\"));\n}\n","server/commercial/quotation-rows.ts":"import {displayUnit} from '../boq/unit.js';\nimport {Decimal} from 'decimal.js';\nimport type { QuoteLine } from './engine.js';\n\n/** Expand customer scope without changing the stored financial groups or amounts. */\nexport function quotationDisplayRows(lines: QuoteLine[]): QuoteLine[] {\n  const members = lines.map(line => {\n    if(line.descriptionOverride)return [{description:line.description,descriptionOverride:true,unit:line.items?.length===1?line.items[0].unit:line.unit,qty:line.items?.length===1?line.items[0].qty:line.qty}];\n    if (line.items?.length) return line.items;\n    // Older saved BESS quotations used one multiline LS cell. Read it without rewriting history.\n    const parts = line.description.split('\\n');\n    const parsed = parts.map(description => description.match(/^(.*?)\\s+\\((\\d+(?:\\.\\d+)?)\\s+([^()]+)\\)$/));\n    if (line.unit === 'LS' && parts.length > 1 && parsed.every(Boolean))\n      return parsed.map(match => ({description:match![1], qty:match![2], unit:match![3]}));\n    return [{description:line.description,unit:line.unit,qty:line.qty}];\n  });\n  const panelQty=lines.filter(line=>line.group===\"solar\").reduce((sum,line)=>sum.add(line.qty),new Decimal(0));\n  return lines.flatMap((line,index) => {\n    if(!line.descriptionOverride && line.items?.length && line.amount!==undefined && line.items.every(i=>i.amount!==undefined)){\n      const items=line.items.map(i=>({...i}));\n      const delta=new Decimal(line.amount).sub(items.reduce((v,i)=>v.add(i.amount!),new Decimal(0))).mul(100).toDecimalPlaces(0);\n      // A displayed introductory offer increase is allocated by its saved allowance,\n      // using integer cents. It never changes the frozen net price or tax calculation.\n      const allowance=items.map(i=>new Decimal(i.offerAllowance??\"0\"));\n      const weights=allowance.some(w=>w.gt(0))?allowance:items.map(i=>new Decimal(i.amount!));\n      const sum=weights.reduce((v,w)=>v.add(w),new Decimal(0));\n      if(!delta.isZero() && sum.gt(0)){\n        const exact=weights.map(w=>delta.abs().mul(w).div(sum));\n        const cents=exact.map(v=>v.floor());\n        let remaining=delta.abs().sub(cents.reduce((v,w)=>v.add(w),new Decimal(0))).toNumber();\n        const order=exact.map((v,i)=>({i,fraction:v.sub(cents[i])})).sort((a,b)=>b.fraction.comparedTo(a.fraction)||a.i-b.i);\n        for(const {i} of order){if(remaining--<=0)break;cents[i]=cents[i].add(1);}\n        items.forEach((item,i)=>item.amount=new Decimal(item.amount!).add(cents[i].mul(delta.isNegative()?-1:1).div(100)).toFixed(2));\n      }else if(!delta.isZero())items.at(-1)!.amount=new Decimal(items.at(-1)!.amount!).add(delta.div(100)).toFixed(2);\n      return items.map(item=>({...item,group:line.group,span:1}));\n    }\n    return members[index].map((item,memberIndex) => ({\n    ...item, group:line.group,\n    ...(memberIndex === 0 && line.amount !== undefined ? {\n      amount:line.amount,\n      span:members.slice(index,index + (line.span ?? 1)).reduce((sum,rows)=>sum+rows.length,0),\n    } : {}),\n  }));\n  }).map(row=>{\n    const job=/^(Installation, Testing|UPS installation|Single-phase installation|Project delivery)/i.test(row.description);\n    const description=!(\"descriptionOverride\" in row && row.descriptionOverride) && row.group===\"structure\" && panelQty.gt(0) ? `${row.description.replace(/ for [\\d,.]+ panels$/i, \"\")} for ${new Intl.NumberFormat(\"en-PK\", {maximumFractionDigits:4}).format(panelQty.toNumber())} panels` : row.description;\n    return {...row,description,unit:job?\"JOB\":displayUnit(row.unit,row.qty),qty:job?\"1\":row.qty};\n  });\n}\n","server/commercial/cni-report.ts":"import { jsPDF } from \"jspdf\";\nimport { autoTable } from \"jspdf-autotable\";\nimport { drawReportLogo } from \"../reports/branding.js\";\nimport { cniWhiteLogo, cniReferenceTerms } from \"./cni-assets.js\";\nimport { displayDate } from \"../display/dates.js\";\nimport type { priceCni } from \"./cni-policy.js\";\nimport { buildApprovedCniPdf } from \"./cni-approved-report.js\";\nexport interface CniSnapshot {\n customer:{name:string;contact_person:string;phone:string;address:string;city:string;province:string;email:string};\n siteName:string;pricing:ReturnType<typeof priceCni>;validityDays:number;preparedBy:string;issuedDate:string;pdfTemplate?:string;\n}\nconst blue=[52,60,145] as const,red=[229,45,59] as const;\nconst money=(v:string)=>new Intl.NumberFormat(\"en-PK\",{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v));\nexport function buildCniPdf(s:CniSnapshot,number:string,draft:boolean) {\n if(s.pdfTemplate === \"PHOTON-APPROVED-1\")return buildApprovedCniPdf(s,number,draft);\n const p=new jsPDF({compress:true});const totalKw=s.pricing.quantity*125,totalKwh=s.pricing.quantity*261;\n p.setProperties({title:number,author:\"Power Zone\"});\n p.setFillColor(...blue);p.rect(0,0,210,297,\"F\");\n p.setFillColor(65,74,161);p.triangle(172,0,210,0,210,297,\"F\");\n p.addImage(cniWhiteLogo,\"PNG\",15,10.6,37.2,23.3);\n p.setFillColor(...red);p.rect(15,39.2,22,1.5,\"F\");\n p.setTextColor(255,255,255);p.setFont(\"helvetica\",\"bold\");p.setFontSize(9);p.text(\"COMMERCIAL & INDUSTRIAL\",15,53.3);\n p.setFontSize(37);p.text([\"Energy storage.\",\"Engineered for\",\"your business.\"],15,70.2,{lineHeightFactor:1.19});\n p.setFont(\"helvetica\",\"normal\");p.setFontSize(12);p.text(\"C&I BESS PROPOSAL\",15,115);\n p.setFont(\"helvetica\",\"bold\");p.setFontSize(30);p.text(`${totalKw} kW`,15,156.6);\n p.setFontSize(8);p.text(\"TOTAL PCS POWER\",15,163.6);p.setFontSize(30);p.text(`${totalKwh} kWh`,15,180.9);\n p.setFontSize(8);p.text(\"TOTAL ENERGY STORAGE\",15,188);p.setFontSize(10);p.text(`${s.pricing.quantity} ${s.pricing.quantity===1?\"CABINET\":\"CABINETS\"}`,15,205.6);\n p.setDrawColor(137,145,207);p.line(15,228.6,195,228.6);p.setFontSize(8);p.text(\"PREPARED FOR\",15,238.4);\n p.setFontSize(17);p.text(p.splitTextToSize(s.customer.name,180).slice(0,2),15,270);\n p.setFont(\"helvetica\",\"normal\");p.setFontSize(7);p.text(`${number}  |  ${displayDate(s.issuedDate)}`,15,273.7);\n const page=(label:string,title:string)=>{p.addPage();drawReportLogo(p);p.setTextColor(...red);p.setFontSize(9);p.setFont(\"helvetica\",\"bold\");p.text(label,15,48);p.setTextColor(...blue);p.setFontSize(24);p.text(title,15,62);};\n const table=(body:any[],startY:number,head?:string[],alignAmounts=false)=>autoTable(p,{startY,head:head?[head]:undefined,body,margin:{left:15,right:15,bottom:20},rowPageBreak:\"avoid\",styles:{font:\"helvetica\",fontSize:10,cellPadding:4},columnStyles:alignAmounts?{0:{cellWidth:120},1:{cellWidth:60,halign:\"right\"}}:undefined,headStyles:{fillColor:[...blue]},alternateRowStyles:{fillColor:[240,242,249]}});\n page(\"01 / INTRODUCTION\",\"A solution for your energy needs.\");\n table([[\"Customer\",s.customer.name],[\"Contact person\",s.customer.contact_person],[\"Phone\",s.customer.phone],[\"Address\",[s.customer.address,s.customer.city,s.customer.province].filter(Boolean).join(\", \")],[\"Site / Project\",s.siteName],[\"Proposal no.\",number],[\"Proposal date\",displayDate(s.issuedDate)],[\"Validity\",`${s.validityDays} days from issue`]],76);\n let y=(p as any).lastAutoTable.finalY+14;p.setTextColor(37,35,50);p.setFont(\"helvetica\",\"normal\");p.setFontSize(10);\n const intro=`Dear ${s.customer.contact_person||\"Customer\"},\\n\\nThank you for considering Power Zone for your energy requirements. We are pleased to present our integrated commercial and industrial energy storage proposal.\\n\\nPrepared by: ${s.preparedBy}\\nPower Zone Engineering & Services`;\n p.text(p.splitTextToSize(intro,175),15,y);\n page(\"02 / TECHNICAL SOLUTION\",\"An integrated cabinet system.\");\n table([[\"System\",`${s.pricing.quantity} x CPS ES-125kW/261kWh`],[\"PCS\",`125 kW per cabinet; AC 400 V / 50 Hz. Total: ${totalKw} kW`],[\"Battery\",`261 kWh per cabinet; 832 V / 314 Ah; 0.5C at 25 C. Total: ${totalKwh} kWh`],[\"Battery management\",\"BMU, control box and communication cables\"],[\"Fire suppression\",\"Aerosol chamber, detectors, alarms and explosion-proof vent\"],[\"Liquid cooling\",\"3 kW liquid cooling machine, pipes and cables per cabinet\"],[\"Auxiliary system\",\"Breakers, UPS and dehumidifier\"],[\"Enclosure\",\"IP55 enclosure and accessories\"],[\"Control unit\",\"BAU and operation monitoring system for Microgrid\"]],78);\n page(\"03 / COMMERCIAL OFFER\",\"A clear, consolidated offer.\");\n autoTable(p,{startY:80,head:[[\"Description\",\"UOM\",\"Qty\",\"Amount (PKR)\"]],body:[[\"CPS ES-125kW/261kWh integrated cabinet system\",\"Cabinet\",String(s.pricing.quantity),money(s.pricing.displayedOffer??s.pricing.standardPayable)]],theme:\"grid\",margin:{left:15,right:15,bottom:20},styles:{font:\"helvetica\",fontSize:10,cellPadding:4},headStyles:{fillColor:[...blue]},columnStyles:{0:{cellWidth:100},1:{cellWidth:20,halign:\"center\",valign:\"middle\"},2:{cellWidth:15},3:{cellWidth:45,halign:\"right\"}},didParseCell(data){if(data.column.index===1){data.cell.styles.halign=\"center\";data.cell.styles.valign=\"middle\";}},rowPageBreak:\"avoid\"});\n const commercialStart=(p as any).lastAutoTable.finalY+8;\n const rows:any[]=[];\n if(s.pricing.standardDiscount)rows.push([\"Offer before standard discount\",`PKR ${money(s.pricing.displayedOffer)}`],[\"Standard discount\",`PKR ${money(s.pricing.standardDiscount)}`]);\n if(s.pricing.discount!==\"0.00\")rows.push([draft?\"Proposed discount - awaiting approval\":\"Management-approved discount\",`PKR ${money(s.pricing.discount)}`]);\n if(s.pricing.presentation===\"Separate\")rows.push([\"Price before GST\",`PKR ${money(s.pricing.beforeTax)}`],[`GST ${s.pricing.taxRate}%`,`PKR ${money(s.pricing.tax)}`]);\n rows.push([\"Total payable\",`PKR ${money(s.pricing.payable)}`]);table(rows,commercialStart,undefined,true);\n y=(p as any).lastAutoTable.finalY+15;p.setFontSize(10);p.setFont(\"helvetica\",\"normal\");p.setTextColor(37,35,50);p.text(p.splitTextToSize(\"Installation, commissioning and delivery are excluded and will be charged as per actual.\",175),15,y);\n page(\"04 / COMMERCIAL TERMS\",\"Terms, warranty & services.\");\n const paragraphs=cniReferenceTerms.replace(/Security Level: Confidential/g,\"\").split(/\\n(?=(?:[1-9]\\. |[A-H]\\. |[1-9]-))/).map(t=>[t.replace(/\\n/g,\" \").replace(/[^\\x20-\\x7e]/g,\"\")]);\n table(paragraphs,78);\n for(let i=1;i<=p.getNumberOfPages();i++){p.setPage(i);if(i>1){p.setFontSize(7);p.setFont(\"helvetica\",\"normal\");p.setTextColor(110,110,120);p.text(`${number} | Page ${i} of ${p.getNumberOfPages()}`,15,289);}if(draft){p.setTextColor(229,45,59);p.setFontSize(10);p.text(\"DRAFT - AWAITING MANAGEMENT APPROVAL\",105,i===1?282:280,{align:\"center\"});}}\n return Buffer.from(p.output(\"arraybuffer\"));\n}\n","server/commercial/cni-approved-report.ts":"import { jsPDF } from \"jspdf\";\nimport { autoTable } from \"jspdf-autotable\";\nimport { Decimal } from \"decimal.js\";\nimport { logo } from \"../reports/brand-assets.js\";\nimport { cniWhiteLogo, cniReferenceTerms } from \"./cni-assets.js\";\nimport { displayDate } from \"../display/dates.js\";\nimport type { CniSnapshot } from \"./cni-report.js\";\n\n// Coordinates and typography reproduce the owner-approved Photon design preview.\n// The selected template is stored on each immutable quotation snapshot.\nexport function buildApprovedCniPdf(s:CniSnapshot,reference:string,draft:boolean) {\n const p=new jsPDF({unit:\"pt\",format:\"a4\",compress:true});const W=595.28,H=841.89;\n const blue=\"#343C91\",red=\"#E52D3B\",ink=\"#252332\",muted=\"#6F6A7B\",light=\"#F0F2F9\";\n const qty=s.pricing.quantity,kw=qty*125,kwh=qty*261;\n const money=(v:string)=>new Decimal(v).toFixed(2).replace(/\\B(?=(\\d{3})+(?!\\d))/g,\",\");\n const text=(x:number,y:number,value:string,size=10,color=ink,bold=false,align:\"left\"|\"right\"=\"left\")=>{\n  p.setFont(\"helvetica\",bold?\"bold\":\"normal\");p.setFontSize(size);p.setTextColor(color);p.text(value,x,H-y,{align});\n };\n const rect=(x:number,y:number,w:number,h:number,color:string,r=0)=>{p.setFillColor(color);if(r)p.roundedRect(x,H-y-h,w,h,r,r,\"F\");else p.rect(x,H-y-h,w,h,\"F\");};\n const para=(value:string,x:number,y:number,width:number,size=10,leading=16,color=ink)=>{\n  p.setFont(\"helvetica\",\"normal\");p.setFontSize(size);p.setTextColor(color);\n  const lines=p.splitTextToSize(value,width) as string[];\n  p.text(lines,x,H-y+size,{lineHeightFactor:leading/size});return y-lines.length*leading-10;\n };\n const footer=(n:number)=>{p.setDrawColor(\"#DCE0EB\");p.line(42,H-48,W-42,H-48);\n  text(42,31,draft?\"CONFIDENTIAL  |  DRAFT - AWAITING MANAGEMENT APPROVAL\":\"CONFIDENTIAL  |  POWER ZONE ENGINEERING & SERVICES\",7,muted);\n  text(W-42,31,`POWER ZONE  /  ${String(n).padStart(2,\"0\")}`,7,muted,false,\"right\");\n };\n const header=(n:number,label:string,title:string,subtitle=\"\")=>{\n  p.addPage();p.addImage(logo,\"PNG\",53.77,38,71.46,45);\n  text(W-179,H-54,\"C&I ENERGY STORAGE\",8,muted);\n  text(42,H-126,label.toUpperCase(),9,red,true);text(42,H-164,title,27,blue,true);\n  if(subtitle)text(42,H-187,subtitle,10,muted);footer(n);\n };\n const fit=(value:string,width:number,size=9)=>{p.setFont(\"helvetica\",\"normal\");p.setFontSize(size);return p.splitTextToSize(value,width) as string[];};\n p.setProperties({title:reference,author:\"Power Zone\"});\n rect(0,0,W,H,blue);p.setFillColor(\"#414AA1\");\n // The original background slant, with the logo's aspect ratio preserved.\n p.lines([[W-365,0],[0,-H],[490-W,0],[365-490,H]],365,H,[1,1],\"F\",true);\n p.addImage(cniWhiteLogo,\"PNG\",42,30,105.2,66);\n rect(42,H-115,62,4,red);text(42,H-151,\"COMMERCIAL & INDUSTRIAL\",9,\"#FFFFFF\",true);\n [\"Energy storage.\",\"Engineered for\",\"your business.\"].forEach((v,i)=>text(42,H-199-i*44,v,37,\"#FFFFFF\",true));\n text(42,H-326,\"C&I BESS PROPOSAL\",12,\"#DFE3FF\");\n text(42,398,`${kw} kW`,32,\"#FFFFFF\",true);text(42,378,\"TOTAL PCS POWER\",8,\"#DFE3FF\");\n text(42,329,`${kwh} kWh`,32,\"#FFFFFF\",true);text(42,309,\"TOTAL ENERGY STORAGE\",8,\"#DFE3FF\");\n text(42,259,`${qty} ${qty===1?\"CABINET\":\"CABINETS\"}`,11,\"#FFFFFF\",true);\n p.setDrawColor(\"#8991CF\");p.line(42,H-194,W-42,H-194);text(42,166,\"PREPARED FOR\",8,\"#DFE3FF\");\n const customerLines=fit(s.customer.name,511,21);customerLines.slice(0,2).forEach((v,i)=>text(42,140-i*23,v,21,\"#FFFFFF\",true));\n if(s.customer.city)text(42,customerLines.length>1?90:116,`${s.customer.city}, Pakistan`,10,\"#DFE3FF\");\n text(42,66,`${reference}  |  ${displayDate(s.issuedDate)}`,8,\"#FFFFFF\");\n if(draft)text(42,44,\"CONFIDENTIAL  /  DRAFT - AWAITING MANAGEMENT APPROVAL\",7,\"#DFE3FF\");\n\n header(2,\"01 / Introduction\",\"A solution for your energy needs.\",[s.customer.name,s.customer.city].filter(Boolean).join(\"  |  \"));\n const details:[[string,string],...Array<[string,string]>]=[[\"Customer\",s.customer.name],[\"Contact person\",s.customer.contact_person],[\"Contact number\",s.customer.phone],[\"Address\",[s.customer.address,s.customer.city,s.customer.province].filter(Boolean).join(\", \")]];\n let detailY=H-250;const measured=details.map(([label,value])=>({label,lines:fit(value||\"-\",385)}));\n const cardHeight=Math.max(123,42+measured.reduce((sum,v)=>sum+Math.max(19,v.lines.length*12+5),0));\n rect(42,H-208-cardHeight,511,cardHeight,light,6);text(56,H-230,\"CUSTOMER & DOCUMENT DETAILS\",9,red,true);\n for(const row of measured){text(56,detailY,row.label,9,muted);row.lines.forEach((v,i)=>text(150,detailY-i*12,v,9));detailY-=Math.max(19,row.lines.length*12+5);}\n let metadataY=H-208-cardHeight-22;\n for(const [label,value] of [[\"Proposal no.\",reference],[\"Proposal date\",displayDate(s.issuedDate)],[\"Validity\",`${s.validityDays} days from issue`]]){\n  text(56,metadataY,label,9,muted);const lines=fit(value,385);lines.forEach((v,i)=>text(150,metadataY-i*12,v,9));metadataY-=Math.max(19,lines.length*12+5);\n }\n let y=metadataY-15;\n for(const value of [`Dear ${s.customer.contact_person||\"Customer\"},`,\"Thank you for considering Power Zone for your requirements. Enclosed is our proposal based on your specifications. We look forward to providing exceptional service and fulfilling your energy needs with reliability and efficiency.\",\"Thank you for the opportunity to work with you. We are confident that our solutions will meet your expectations and bring value to your operations.\"])y=para(value,42,y,510);\n y-=5;text(42,y,\"Best Regards,\");y-=25;\n for(const value of [\"Abu Bakar Siddique\",\"Director Business Development\",\"Power Zone Engineering & Services\",\"Cell: +92 323 7500128\",\"Email: abubakar@powerzone.com.pk\"]){text(42,y,value,10,ink,value===\"Abu Bakar Siddique\");y-=15;}\n rect(42,74,511,69,light,8);text(60,125,\"YOUR PROPOSED SYSTEM\",9,red,true);text(60,102,`${qty} x CPS ES-125kW/261kWh`,16,blue,true);text(60,84,`${kw} kW PCS  /  ${kwh} kWh storage`,11,muted);\n\n header(3,\"02 / Technical solution\",\"An integrated cabinet system.\",\"Detailed technical scope. One consolidated commercial offer.\");\n const technical=[[\"PCS unit\",\"Rated power: 125 kW; output AC 400 V / 50 Hz.\"],[\"Battery system\",\"832 V / 314 Ah / 261 kWh; 0.5C at 25 degrees C battery rack.\"],[\"Battery management\",\"BMU, control box and communication cables.\"],[\"Fire suppression\",\"Aerosol chamber, detectors and alarms, explosion-proof vent.\"],[\"Liquid cooling\",\"3 kW liquid cooling machine with pipes and cables.\"],[\"Auxiliary system\",\"Auxiliary system, breakers, UPS and dehumidifier.\"],[\"Cabinet enclosure\",\"1000 x 1400 x 2400 mm; IP55 with all necessary accessories.\"],[\"BAU\",\"BAU-CPS ES-125kW/261kWh\"],[\"EMS\",\"Local operation monitoring system for Microgrid.\"]];\n y=H-226;technical.forEach(([a,b],i)=>{if(i%2===0)rect(42,y-46,511,54,light);text(54,y-10,a,10,blue,true);para(b,225,y,310,9,14);y-=60;});\n\n header(4,\"03 / Commercial offer\",\"A clear, consolidated offer.\",\"One consolidated commercial offer. No component pricing.\");\n y=H-230;rect(42,y-45,511,45,blue,5);text(56,y-28,\"CPS ES-125kW/261kWh\",12,\"#FFFFFF\",true);text(540,y-28,`${qty} ${qty===1?\"CABINET\":\"CABINETS\"}`,11,\"#FFFFFF\",true,\"right\");\n const offer=s.pricing.displayedOffer??s.pricing.standardPayable;\n const rows:Array<[string,string]>=[[\"Standard unit offer price\",`PKR ${money(new Decimal(offer).div(qty).toFixed(2))}`],[\"Quantity\",`${qty} ${qty===1?\"cabinet\":\"cabinets\"}`],[\"Offer before discounts\",`PKR ${money(offer)}`]];\n if(s.pricing.standardDiscount)rows.push([\"Management-approved discount\",`PKR ${money(s.pricing.standardDiscount)}`]);\n if(new Decimal(s.pricing.discount).gt(0))rows.push([\"Special discount\",`PKR ${money(s.pricing.discount)}`]);\n if(s.pricing.presentation===\"Separate\")rows.push([\"Price before GST\",`PKR ${money(s.pricing.beforeTax)}`],[`GST ${s.pricing.taxRate}%`,`PKR ${money(s.pricing.tax)}`]);\n rows.push([\"Total payable\",`PKR ${money(s.pricing.payable)}`]);\n y-=81;const spacing=Math.min(58,340/rows.length);\n rows.forEach(([a,b],i)=>{const last=i===rows.length-1;if(last)rect(42,y-14,511,Math.min(48,spacing+12),light,5);text(55,y,a,11,blue,last);text(540,y,b,12,blue,last,\"right\");y-=spacing;});\n para(\"Installation, commissioning, and delivery are excluded and will be charged as per actual.\",42,180,510,9,14);\n\n const raw=cniReferenceTerms.replace(/Security Level: Confidential/g,\"\").replace(/±/g,\"+/-\").replace(/℃/g,\" degrees C\");\n const blocks=raw.split(/\\n(?=(?:Notes:|[1-9]\\. |[A-H]\\. |[1-9]-))/).map(v=>v.replace(/\\n/g,\" \").replace(/[^\\x20-\\x7e]/g,\"\"));\n const joined:string[]=[];for(const block of blocks){const last=joined.at(-1);if(last&&/^(?:Notes:|[1-9]\\. )/.test(last)&&last.length<100&&!/^[1-9]\\. /.test(block))joined[joined.length-1]+=\"\\n\\n\"+block;else joined.push(block);}\n let n=5;header(n,\"04 / Commercial terms\",\"Terms, warranty & services.\");y=H-223;\n for(const block of joined){const lines=fit(block,511);const height=lines.length*14;\n  if(block.startsWith(\"5. Warranty and Services\")){\n   // Restore the reference's structured services table instead of extracted prose.\n   if(y-220<72){header(++n,\"04 / Commercial terms continued\",\"Terms, warranty & services.\");y=H-223;}\n   text(42,y-9,\"5. Warranty and Services in Main Offer:\",9);\n   autoTable(p,{startY:H-y+24,head:[[\"No.\",\"Service item\",\"Description\",\"Price (PKR)\"]],body:[\n    [{content:\"1\",rowSpan:2},{content:\"Warranty\",rowSpan:2},\"PCS - 3 Years\",\"Included\"],\n    [\"Battery - 3 Years\",\"Included\"],\n    [{content:\"2\",rowSpan:2},{content:\"Training\",rowSpan:2},\"Remote Training: Product introduction, installation, commissioning, maintenance and troubleshooting\",\"Free\"],\n    [\"On Site\",\"Included\"],\n    [\"3\",\"On-Site\",\"Supervision on commissioning\",\"Included\"],\n    [\"4\",\"Remote\",\"Power Zone Service Hotline\",\"Included\"]\n   ],theme:\"grid\",margin:{left:42,right:42,bottom:72},styles:{font:\"helvetica\",fontSize:9,cellPadding:5,textColor:ink,lineColor:\"#DCE0EB\",lineWidth:0.4},headStyles:{fillColor:blue,textColor:\"#FFFFFF\"},columnStyles:{0:{cellWidth:30},1:{cellWidth:85},2:{cellWidth:301},3:{cellWidth:95.28}},rowPageBreak:\"avoid\"});\n   y=H-(p as any).lastAutoTable.finalY-13;continue;\n  }\n  if(height>H-223-72)throw new Error(\"A complete terms item exceeds one page.\");\n  if(y-height<72){header(++n,\"04 / Commercial terms continued\",\"Terms, warranty & services.\");y=H-223;}\n  para(block,42,y,511,9,14);y-=height+13;\n }\n return Buffer.from(p.output(\"arraybuffer\"));\n}\n","server/commercial/cni-assets.ts":"export const cniWhiteLogo = \"data:image/png;base64,\";\nexport const cniReferenceTerms = \"Notes:\\n1- Certified that goods supplied under this quotation, were imported by us and income tax under\\nsection 148 has already been paid on these goods at import stage.\\nAccordingly, the provisions of Section 153(1) of the Income Tax Ordinance, 2001 are not\\napplicable at the time of payment against this invoice.\\n1. Payment Terms\\nA. This quotation is based on the following payment terms and subject to a credit check and approval.\\nB. Hundred percent (100%) of the Contract Price shall be billed in PKR immediately upon the contract\\nsignature.\\nC. Production will only commence upon receipt of the advance payment or as agreed in writing by\\nPower Zone. Any delay in payments outside of the agreed payment terms will result in the suspension\\nof all works.\\n2. Price\\nA. Installation, commissioning, and delivery are excluded and will be charged as per actual.\\nB. Prices quoted in PKR and ONLY refer to the devices in the table above. Initial spare parts and\\nspecial tools are included, and specifications and quantities can refer to Section 4 and 5.\\nC. Battery cell OEM is within REPT, EVE, CATL which is NOT nominated.\\nD. Due to long intervals before delivery, price variance in battery cells may have big impact on the\\nprice. When battery cell price variation (\\u00b1) is larger 3% one month before delivery (the baseline can be\\n3rd party source to be agreed by both parties, for example Shanghai Metals Market,\\nhttps://www.metal.com/, or LME), both the buyer and seller have the right to negotiate and modify the\\nquotation price.\\nE. The quotation is calculated based on the provided specifications; if there are changes to these\\nspecifications, the price will be recalculated.\\nF. The quotation does include requirements for relevant certifications.\\nG. Any unmentioned requirements will be priced according to the standards of Power Zone.\\nH. The price is calculated at the current exchange Rate of PKR 278 to 1 USD, a fluctuation of greater\\nthan 5% +/- will change the prices accordingly.\\n3. Initial Spare Parts\\n(if any)\\n4. Special Tools\\n(if any)\\n5. Warranty and Services in Main Offer:\\nNo. Service Item Description Price (PKR)\\nPCS 3 Years Included\\n1 Warranty\\nBattery 3 Years Included\\nRemote Training:\\nProduct Introduction, installation, commissioning,\\n2 Training Free\\nmaintenance and troubleshooting\\nOn Site: Included\\n3 On-Site Supervision on commissioning Included\\n4 Remote Power Zone Service Hotline Included\\n6. Validity Period:\\nThis quotation is valid for 7 days from date of issue. Power Zone reserves the right to vary the price\\nquoted within this validity period in the case of significant input cost movements/variations and\\nexchange rate.\\n7. Transfer of Product Title and Risk:\\nTitle of the Product shall be transferred to the Customer upon full payment to Power Zone. Risk of the\\nProduct shall be transferred to Customer in accordance with Trade Term (Incoterms 2010 by ICC).\\n8. Confidentiality:\\nAll information received with this proposal (quotation) shall be kept confidential and be used for\\ncustomer internal review / project contract / PO implementation purposes only.\\n9. Intellectual Property Rights:\\nNeither party is granting its Intellectual Property Rights to the other party under this proposal\\n(quotation). The Customer is granted a non-exclusive and non-transferable license to use the\\nsoftware supplied under this proposal (quotation) for operational purpose only.\";\n","server/orders/report.ts":"import { displayUnit } from \"../boq/unit.js\";\nimport { appendPeachtreePage } from \"./peachtree-report.js\";\nimport { quotationTypeLabel } from \"./sale-type.js\";\nimport { ipoPresentation } from \"./presentation.js\";\nimport { jsPDF } from \"jspdf\";\nimport { autoTable } from \"jspdf-autotable\";\nimport {\n  drawReportLogo,\n  drawReportFooter,\n  reportBottomMargin,\n} from \"../reports/branding.js\";\nconst clean = (s: unknown) =>\n  String(s ?? \"\")\n    .replaceAll(\"×\", \"x\")\n    .replace(/[–—]/g, \"-\")\n    .replace(/[^\\n\\x20-\\x7e\\xa0-\\xff]/g, \"\");\nconst money = (s: string) =>\n  Number(s).toLocaleString(\"en-PK\", {\n    minimumFractionDigits: 2,\n    maximumFractionDigits: 2,\n  });\nexport function buildIpoPdf(s: any, number?: string, division = s.peachtree) {\n  const pdf = new jsPDF({ unit: \"mm\", format: \"a4\", compress: true });\n  pdf.setProperties({\n    title: number ?? \"Draft IPO\",\n    author: \"Power Zone Engineering & Services\",\n  });\n  drawReportLogo(pdf);\n  pdf.setFontSize(12);\n  pdf.text(\n    number ? \"INTERNAL PURCHASE ORDER\" : \"DRAFT INTERNAL PURCHASE ORDER\",\n    14,\n    37,\n  );\n  pdf.setFontSize(8);\n  pdf.text(\"POWER ZONE ENGINEERING & SERVICES (PVT) LIMITED\", 14, 42);\n  const i = s.input;\n  const view = ipoPresentation({\n    ...s,\n    quotationType: division ?? s.quotationType,\n  });\n  const taxDeal=s.quotationType?.saleType !== \"Cash Deal\";\n  const entries = [\n    [\"IPO / Job reference\",number ?? \"DRAFT\",\"Quotation reference\",s.quotationNumber || \"Not available\"],\n    [\"Company to invoice\",i.invoiceCompany,\"Tax deal\",taxDeal?\"Yes\":\"No\"],\n    [\"Prepared by\",\"Atif\",\"Checked by\",\"Atif\"],\n    [\"Customer\",s.customer.name,\"Site / branch\",`${s.siteName ?? \"Not entered\"} / ${s.siteCode ?? \"Not entered\"}`],\n    [\"Customer PO / approval\",i.poNumber || i.evidenceNotes || \"Not entered\",\"PO / approval date\",i.orderDate],\n    ...(taxDeal?[[\"Customer NTN\",i.customerNtn || \"Not entered\",\"Customer STRN\",i.customerStrn || \"Not entered\"]]:[]),\n    [\"Billing address\",i.billingAddress || \"Not entered\",\"Customer contact\",`${i.contactPerson || s.customer.contactPerson || \"Not entered\"} / ${i.phone || s.customer.phone || \"Not entered\"}`],\n  ];\n  autoTable(pdf, {\n    startY: 46,\n    theme: \"grid\",\n    margin: { left: 14, right: 14, bottom: reportBottomMargin },\n    styles: { fontSize: 7, cellPadding: 1.4 },\n    columnStyles: {\n      0: { cellWidth: 27 },\n      1: { cellWidth: 64 },\n      2: { cellWidth: 27 },\n      3: { cellWidth: 64 },\n    },\n    body: [\n      ...entries,\n      [\"Quotation type\", quotationTypeLabel(division ?? s), \"\", \"\"],\n    ].map((row) => row.map(clean)),\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 4,\n    theme: \"grid\",\n    margin: { left: 14, right: 14, bottom: reportBottomMargin },\n    styles: { fontSize: 7, cellPadding: 1.3 },\n    headStyles: { fillColor: [61, 63, 146], fontSize: 7 },\n    head: [[\"Description\", \"Qty\", \"Unit\", view.included ? \"Rate\" : \"Rate excl. GST\", view.included ? \"Amount\" : \"Amount excl. GST\"]],\n    columnStyles: {0:{cellWidth:100},1:{halign:\"center\",cellWidth:10},2:{halign:\"center\",cellWidth:12},3:{halign:\"right\"},4:{halign:\"right\"}},\n    body:view.rows.map(l=>[clean(l.description),l.qty,displayUnit(l.unit,l.qty),money(l.rate),money(l.amount)]),\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 3,\n    theme: \"plain\",\n    margin: { left: 14, right: 14, bottom: reportBottomMargin },\n    styles: { fontSize: 8, cellPadding: 1.2 },\n    body: [\n      ...(!view.included\n        ? [\n            [\"Grand total before tax\", {content:money(view.amount),styles:{halign:\"right\" as const}}],\n            ...view.taxSummary.map((tax)=>[tax.label,{content:money(tax.amount),styles:{halign:\"right\" as const}}]),\n          ]\n        : []),\n      [\"GRAND TOTAL (PKR)\", {content:money(s.allocation.total),styles:{halign:\"right\",fontStyle:\"bold\"}}],\n      ...(i.paymentMode ? [[\"Payment mode\", clean(i.paymentMode)]] : []),\n      ...(i.salesSource ? [[\"Sales source\", clean(i.salesSource)]] : []),\n      ...(i.remarks ? [[\"Remarks\", clean(i.remarks)]] : []),\n    ],\n  });\n  if (division) appendPeachtreePage(pdf, s, division, number ?? \"DRAFT IPO\");\n  drawReportFooter(\n    pdf,\n    number\n      ? `${number} / IPO & Peachtree Division`\n      : \"DRAFT IPO & Peachtree Division\",\n  );\n  return Buffer.from(pdf.output(\"arraybuffer\"));\n}\n","server/orders/peachtree-report.ts":"import {CASH_PROFIT_NOTE, retainedGst} from \"../commercial/deal.js\";\nimport {Decimal} from \"decimal.js\";\nimport { jsPDF } from \"jspdf\";\nimport { autoTable } from \"jspdf-autotable\";\nimport { drawReportLogo, drawReportFooter } from \"../reports/branding.js\";\nimport { quotationTypeLabel } from \"./sale-type.js\";\nimport type { peachtreeDivision } from \"./peachtree.js\";\nconst money = (s: string) =>\n  Number(s).toLocaleString(\"en-PK\", {\n    minimumFractionDigits: 2,\n    maximumFractionDigits: 2,\n  });\nconst text = (v: unknown) =>\n  String(v ?? \"\")\n    .replace(/[–—]/g, \"-\")\n    .replace(/[^\\n\\x20-\\x7e\\xa0-\\xff]/g, \"\");\nexport function appendPeachtreePage(\n  pdf: jsPDF,\n  s: any,\n  d: ReturnType<typeof peachtreeDivision>,\n  number: string,\n) {\n  pdf.addPage();\n  drawReportLogo(pdf);\n  pdf.setFontSize(12);\n  pdf.text(\"PEACHTREE DIVISION\", 14, 38);\n  pdf.setFontSize(9);\n  pdf.text(\"POWER ZONE ENGINEERING & SERVICES (PVT) LIMITED\", 14, 44);\n  autoTable(pdf, {\n    startY: 50,\n    theme: \"plain\",\n    styles: { fontSize: 9, cellPadding: 2 },\n    body: [\n      [\"IPO\", number],\n      [\"Quotation\", text(s.quotationNumber)],\n      [\"BOQ\", text(s.boqNumber)],\n      [\"Customer\", text(s.customer.name)],\n      [\"Entry basis\", d.basis],\n      [\"Quotation type\", text(quotationTypeLabel(d))],\n    ],\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 7,\n    theme: \"grid\",\n    headStyles: { fillColor: [61, 63, 146] },\n    footStyles: { fillColor: [61, 63, 146] },\n    styles: { fontSize: 10, cellPadding: 3 },\n    columnStyles: {0:{cellWidth:32},1:{cellWidth:105},2:{halign:\"right\"}},\n    head: [[\"PT phase\", \"Item / quantity description\", d.saleType === \"Cash Deal\" ? \"Selling value (PKR)\" : \"Selling excl. GST (PKR)\"]],\n    body: d.phases.flatMap((p:any)=>[[p.name,text(p.description || \"Description not recorded\"),money(p.amount)],...(p.name === \"BMS\"?[[\"BESS Total\",\"Subtotal\",money(d.phases.filter(p=>[\"Inverter\",\"Batteries\",\"BMS\"].includes(p.name)).reduce((v,p)=>v.add(p.amount),new Decimal(0)).toFixed(2))]]:[])]),\n    foot: [[\"PHASE TOTAL\",\"\", {content:money(d.phaseTotal),styles:{halign:\"right\"}}]],\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 6,\n    theme: \"plain\",\n    styles: { fontSize: 9, cellPadding: 2 },\n    columnStyles: { 1: { halign: \"right\" } },\n    body:\n      d.version >= 2 && d.taxMode === \"Tax Included\"\n        ? [[\"IPO payable\", money(d.ipoPayable)]]\n        : [\n            [\"IPO total before tax\", money(d.ipoBeforeTax)],\n            [\"IPO tax (separate reconciliation)\", money(d.ipoTax)],\n            [\"IPO payable\", money(d.ipoPayable)],\n          ],\n  });\n  const policy =\n    d.version >= 2\n      ? \"Phase entries retain the original accepted quotation selling values and margins after allocating the approved discount to eligible 18% items. Solar remains unchanged; no margin redistribution is applied.\"\n      : d.presentation === \"No Breakup\"\n        ? \"Solar is allocated at cost x 1.10, or cost x 1.21 for the tax-inclusive phase division. The remaining value is allocated across other phases in proportion to approved phase costs.\"\n        : d.presentation === \"Basic Breakup\"\n          ? `BESS and Balance/EPC selling values are pooled and redistributed using their combined effective before-tax markup (${d.effectivePooledMarkup}%). Separately priced Solar, Structure and Earthing retain their net accepted values.`\n          : \"Phase entries retain the accepted item selling values after discount allocation.\";\n  pdf.setFontSize(8);\n  pdf.text(\n    pdf.splitTextToSize(\n      text(\n        `${policy} ${d.phases.length===2 && d.phases[0].name===\"BESS\" ? \"BESS contains inverter, batteries and BMS; EPC contains every other project item.\" : \"EPC contains all items outside Solar, Structure, Inverter, Batteries and BMS.\"} This internal phase division does not alter the accepted quotation, IPO payable or tax treatment. ${retainedGst(d)?CASH_PROFIT_NOTE:\"GST payable is excluded from profit.\"}`,\n      ),\n      180,\n    ),\n    14,\n    (pdf as any).lastAutoTable.finalY + 8,\n  );\n}\nexport function buildPeachtreePdf(\n  s: any,\n  d: ReturnType<typeof peachtreeDivision>,\n  number: string,\n) {\n  const pdf = new jsPDF({ unit: \"mm\", format: \"a4\", compress: true });\n  pdf.setProperties({\n    title: `${number} - Peachtree Division`,\n    author: \"Power Zone Engineering & Services\",\n  });\n  appendPeachtreePage(pdf, s, d, number);\n  pdf.deletePage(1);\n  drawReportFooter(pdf, `${number} / Peachtree Division`);\n  return Buffer.from(pdf.output(\"arraybuffer\"));\n}\n","server/orders/presentation.ts":"import { Decimal } from \"decimal.js\";\nexport function ipoPresentation(snapshot: any) {\n  const presentation =\n    snapshot.quotationType?.presentation ??\n    snapshot.peachtree?.presentation ??\n    snapshot.presentation ??\n    \"Full Breakup\";\n  const deal=snapshot.quotationType?.saleType ?? snapshot.peachtree?.saleType;\n  const included = deal === \"Cash Deal\" || deal !== \"Tax Deal\" &&\n    (snapshot.quotationType?.taxMode ??\n      snapshot.peachtree?.taxMode ??\n      snapshot.taxMode) === \"Tax Included\";\n  const source = snapshot.allocation.lines.filter(\n    (l: any) => Number(l.qty) > 0 || Number(l.total) > 0,\n  );\n  const sum = (ls: any[], key: string) =>\n    ls.reduce((v: Decimal, l: any) => v.add(l[key]), new Decimal(0)).toFixed(2);\n  const groups: any[][] =\n    presentation === \"No Breakup\"\n      ? [source]\n      : presentation === \"Basic Breakup\"\n        ? [...new Set(source.map((l: any) => l.group))].map((group) =>\n            source.filter((l: any) => l.group === group),\n          )\n        : source.map((l: any) => [l]);\n  const rows = groups.map((ls) => {\n    const combined = ls.length > 1 || presentation === \"No Breakup\";\n    const amount = sum(ls, included ? \"total\" : \"beforeTax\"),\n      qty = combined ? \"1\" : ls[0].qty;\n    return {\n      description: ls\n        .map((l) =>\n          combined ? `${l.description} (${l.qty} ${l.unit})` : l.description,\n        )\n        .join(\"\\n\"),\n      qty,\n      unit: combined ? \"LS\" : ls[0].unit,\n      amount,\n      rate: new Decimal(qty).gt(0)\n        ? new Decimal(amount).div(qty).toFixed(6)\n        : \"0\",\n      taxRate: included\n        ? \"0\"\n        : [...new Set(ls.map((l) => l.taxRate))].join(\" / \"),\n      tax: included ? \"0.00\" : sum(ls, \"tax\"),\n      total: sum(ls, \"total\"),\n    };\n  });\n  return {\n    presentation,\n    included,\n    rows,\n    taxSummary: included ? [] : [\n      {label:\"Solar panel sales tax @10%\",amount:sum(source.filter((l:any)=>new Decimal(l.taxRate).eq(10)),\"tax\")},\n      {label:\"Sales tax on other items @18%\",amount:sum(source.filter((l:any)=>new Decimal(l.taxRate).eq(18)),\"tax\")},\n    ],\n    amount: included ? snapshot.allocation.total : snapshot.allocation.subtotal,\n    tax: included ? \"0.00\" : snapshot.allocation.tax,\n    total: snapshot.allocation.total,\n  };\n}\n","server/orders/peachtree.ts":"import {cashDeal} from \"../commercial/deal.js\";\nimport { Decimal } from \"decimal.js\";\nimport type { BoqSnapshot } from \"../boq/engine.js\";\nimport type { PricingSnapshot } from \"../commercial/engine.js\";\nimport type { allocateDiscount } from \"./allocation.js\";\nimport { HttpError } from \"../http/errors.js\";\nconst names = [\n  \"Solar Panels\",\n  \"Structure\",\n  \"Inverter\",\n  \"Batteries\",\n  \"BMS\",\n  \"EPC\",\n];\nconst D = (v: string) => new Decimal(v);\nconst money = (v: Decimal) =>\n  v.toDecimalPlaces(2, Decimal.ROUND_HALF_UP).toFixed(2);\nexport function peachtreeDivision(\n  allocation: ReturnType<typeof allocateDiscount>,\n  boq: BoqSnapshot,\n  pricing: PricingSnapshot,\n  legacyAdditionalCost = \"0\",\n) {\n  const included = cashDeal(pricing.input) || !pricing.input.saleType && pricing.input.taxMode === \"Tax Included\";\n  const taxMode = included?\"Tax Included\":\"Show Sales Tax Separately\";\n  const field = included ? \"total\" : \"beforeTax\";\n  const target = D(included ? allocation.total : allocation.subtotal);\n  if(boq.survey.family === \"direct-product\") {\n    const phases=names.map(name=>({name,amount:money(allocation.lines.filter(line=>{\n      const source=boq.lines.find(l=>l.key===line.description);\n      const category=source?.phase === \"Solar Panels\" ? \"Solar Panels\" : source?.phase === \"Structure\" ? \"Structure\" : /^HYB-/.test(source?.key ?? \"\") ? \"Inverter\" : /^BAT-/.test(source?.key ?? \"\") ? \"Batteries\" : /^(CH-BMS-|BMS-)/.test(source?.key ?? \"\") ? \"BMS\" : \"EPC\";\n      return category === name;\n    }).reduce((sum,line)=>sum.add(line[field]),D(\"0\")))}));\n    if(!phases.reduce((sum,p)=>sum.add(p.amount),D(\"0\")).eq(target))throw new HttpError(422,\"Product classifications do not reconcile with the IPO.\");\n    return {version:2,saleType:pricing.input.saleType,cashGstTreatment:pricing.input.cashGstTreatment,policy:\"exact-accepted-quotation-v2\",presentation:pricing.input.presentation,taxMode,basis:included?\"Tax-inclusive selling values\":\"Selling values excluding tax\",effectivePooledMarkup:null,phases,phaseTotal:money(target),ipoBeforeTax:allocation.subtotal,ipoTax:allocation.tax,ipoPayable:allocation.total};\n  }\n  if(boq.survey.family === \"bess-only\"){\n    const phases=[{name:\"BESS\",amount:money(allocation.lines.filter(l=>l.group===\"bess\").reduce((v,l)=>v.add(l[field]),D(\"0\")))},{name:\"EPC\",amount:money(allocation.lines.filter(l=>l.group!==\"bess\").reduce((v,l)=>v.add(l[field]),D(\"0\")))}];\n    if(!D(phases[0].amount).add(phases[1].amount).eq(target))throw new HttpError(422,\"BESS/EPC totals do not reconcile with the IPO.\");\n    return {version:2,saleType:pricing.input.saleType,cashGstTreatment:pricing.input.cashGstTreatment,policy:\"exact-accepted-quotation-v2\",presentation:pricing.input.presentation,taxMode,basis:included?\"Tax-inclusive selling values\":\"Selling values excluding tax\",effectivePooledMarkup:null,phases,phaseTotal:money(target),ipoBeforeTax:allocation.subtotal,ipoTax:allocation.tax,ipoPayable:allocation.total};\n  }\n  const amounts = names.map((_, phase) =>\n    allocation.lines\n      .filter((_, i) => (phase < 5 ? i === phase : i >= 5))\n      .reduce((v, l) => v.add(l[field]), D(\"0\")),\n  );\n  const policy = \"exact-accepted-quotation-v2\";\n  const effectiveMarkup = null;\n  if (money(amounts.reduce((v, a) => v.add(a), D(\"0\"))) !== money(target))\n    throw new HttpError(\n      422,\n      \"Peachtree phase totals do not reconcile with the IPO.\",\n    );\n  return {\n    version: 2,\n    saleType:pricing.input.saleType,cashGstTreatment:pricing.input.cashGstTreatment,\n    policy,\n    presentation: pricing.input.presentation,\n    taxMode,\n    basis: included\n      ? \"Tax-inclusive selling values\"\n      : \"Selling values excluding tax\",\n    effectivePooledMarkup: effectiveMarkup,\n    phases: names.map((name, i) => ({ name, amount: money(amounts[i]) })),\n    phaseTotal: money(target),\n    ipoBeforeTax: allocation.subtotal,\n    ipoTax: allocation.tax,\n    ipoPayable: allocation.total,\n  };\n}\n","server/ubl/ipo-sample-report.ts":"import {jsPDF} from 'jspdf';\nimport {autoTable} from 'jspdf-autotable';\nimport {drawReportLogo,drawReportFooter,reportBottomMargin} from '../reports/branding.js';\n\nimport type {ublIpoSample} from './ipo-sample.js';\nimport {Decimal} from 'decimal.js';\nconst money=(v:string)=>new Decimal(v).toFixed(2).replace(/\\B(?=(\\d{3})+(?!\\d))/g,',');\nconst right=(v:string)=>({content:money(v),styles:{halign:'right' as const}});\nexport function ublIpoSamplePdf(s:ReturnType<typeof ublIpoSample>, kind:'ipo'|'pt'|'pack'='pack'){\n const pdf=new jsPDF({unit:'mm',format:'a4',compress:true});\n const workflow=s.documentStatus==='Submitted to Accounts';\n const reference=`IPO ${s.legacyIpoNumber} / IPO & Peachtree Division / ${s.documentStatus==='Historical registered'?'HISTORICAL REGISTERED':workflow?'SUBMITTED TO ACCOUNTS':'REVIEW SAMPLE'}`;\n const stage=s.pricingStage==='Revised'?'Final / Revised':s.pricingStage;\n drawReportLogo(pdf);pdf.setFontSize(12);pdf.text('INTERNAL PURCHASE ORDER',14,37);pdf.setFontSize(8);pdf.text('POWER ZONE ENGINEERING & SERVICES (PVT) LIMITED',14,42);\n autoTable(pdf,{startY:46,theme:'grid',margin:{left:14,right:14,bottom:reportBottomMargin},styles:{fontSize:7,cellPadding:1.4},columnStyles:{0:{cellWidth:27},1:{cellWidth:64},2:{cellWidth:27},3:{cellWidth:64}},body:[\n  ['Job / IPO reference',`CHP-${s.legacyIpoNumber}`,'Customer PO',s.poNumber],\n  ['Company to invoice','PZES (PVT Ltd)','Tax deal','Yes'],\n  ['Prepared by','Atif','Checked by','Atif'],\n  ['Customer',s.customer,'Quotation reference','Approved UBL configuration'],\n  ['Customer contact',s.customerMaster?.contact_person||'Not entered','Contact number',s.customerMaster?.phone||'Not entered'],\n  ['Billing address',s.customerMaster?.address||'Not entered','Customer NTN / STRN','See customer PO / verify before invoice'],\n  ['Site',s.siteName,'Branch code',s.branchCode],\n  ['Configuration',s.configuration,'Pricing stage',stage],\n  ['Region',s.region,'Main city',s.mainCity||'Not entered'],\n  ['PO issue date',s.poIssuedDate,'Document status',s.documentStatus==='Historical registered'?'Historical registered':workflow?'Submitted to Accounts - awaiting acceptance':'Review sample - not issued'],\n  ['Quotation type','UBL Solar - Show Sales Tax Separately','','']\n ]});\n autoTable(pdf,{startY:(pdf as any).lastAutoTable.finalY+4,theme:'grid',margin:{left:14,right:14,bottom:reportBottomMargin},styles:{fontSize:8,cellPadding:2},headStyles:{fillColor:[61,63,146]},head:[['Description','Qty','Unit','Rate excl. GST','Amount excl. GST']],columnStyles:{0:{cellWidth:80},1:{halign:'right',cellWidth:25},2:{cellWidth:13},3:{halign:'right'},4:{halign:'right'}},body:s.billing.map(r=>[r.name,r.name==='Solar Panels'?new Decimal(s.agreedWatts??Number(s.configuration.split('-')[0])*1000).toFixed(0).replace(/\\B(?=(\\d{3})+(?!\\d))/g,','):'1',r.name==='Solar Panels'?'W':'JOB',r.name==='Solar Panels'?money(String(s.panelSellingRate??44)):money(r.sellingExcludingGst),money(r.sellingExcludingGst)])});\n autoTable(pdf,{startY:(pdf as any).lastAutoTable.finalY+3,theme:'plain',margin:{left:14,right:14,bottom:reportBottomMargin},styles:{fontSize:8,cellPadding:1.8},columnStyles:{0:{cellWidth:60},1:{cellWidth:122,halign:'right'}},body:[\n  ['Subtotal excluding GST',right(s.totalSellingExcludingGst)],\n  ['Solar panel sales tax @10%',right(s.billing[0].gst)],\n  ['Installations sales tax @18%',right(s.billing[1].gst)],\n  ['GRAND TOTAL (PKR)',{content:money(s.totalPayable),styles:{halign:'right',fontStyle:'bold'}}],\n  ['Remarks',{content:'Panel wattage is subject to availability. Confirm actual installed wattage against the verified IRR before invoicing. Panel invoicing uses actual watts at the agreed rate; installations balance the approved total. Cable adjustments require separate authorization. '+(s.documentStatus==='Historical registered'?'Historical registration; no invoice or Accounts handoff.':workflow?'IPO submitted to Accounts; invoice and confirmed BOQ issuance remain separate.':'Review sample - not issued.'),styles:{halign:'left'}}]\n ]});\n pdf.addPage();drawReportLogo(pdf);pdf.setFontSize(12);pdf.text('PEACHTREE DIVISION',14,38);pdf.setFontSize(9);pdf.text('POWER ZONE ENGINEERING & SERVICES (PVT) LIMITED',14,44);\n autoTable(pdf,{startY:50,theme:'plain',styles:{fontSize:9,cellPadding:2},body:[['Job / IPO',`CHP-${s.legacyIpoNumber}`],['Customer PO',s.poNumber],['Customer',s.customer],['Site / branch',`${s.siteName} / ${s.branchCode}`],['Configuration / pricing stage',`${s.configuration} / ${stage}`],['Entry basis','Selling values excluding tax'],['Quotation type','UBL Solar - Show Sales Tax Separately']]});\n const body:any[]=[];\n const dual=['30-30-40','35-30-40'].includes(s.configuration),batteryQty=dual?8:6;\n const descriptions:Record<string,string>={'Solar Panels':`${s.agreedWatts ?? Number(s.configuration.split('-')[0])*1000} W agreed capacity - confirm available panel brand and wattage before invoicing`,'Structure':'CH-Structure - Customized elevated structure','Inverter':`${dual?2:1} x ${dual?'CH-PCS-HYB-3P-015':'CH-PCS-HYB-3P-020'}`,'Batteries':`${batteryQty} x CH-BAT-HV-05 KW`,'BMS':'2 x CH-BMS-HV - IP65 battery control and safety unit','EPC':'CH-EPC - Installation and balance of system'};\n\n for(const p of s.phases){body.push([p.name,descriptions[p.name]||'Not recorded',right(p.sellingExcludingGst)]);if(p.name==='BMS')body.push([{content:'BESS Total (subtotal)',styles:{fontStyle:'bold',fillColor:[246,246,252]}},'Subtotal',{content:money(s.phases.filter(v=>['Inverter','Batteries','BMS'].includes(v.name)).reduce((v,p)=>v.add(p.sellingExcludingGst),new Decimal(0)).toFixed(2)),styles:{halign:'right',fontStyle:'bold',fillColor:[246,246,252]}}]);}\n autoTable(pdf,{startY:(pdf as any).lastAutoTable.finalY+7,theme:'grid',headStyles:{fillColor:[61,63,146]},footStyles:{fillColor:[61,63,146]},styles:{fontSize:8,cellPadding:2},columnStyles:{0:{cellWidth:32},1:{cellWidth:108},2:{halign:'right'}},head:[['PT phase','Item / quantity description','Selling excl. GST']],body,foot:[['PHASE TOTAL','',right(s.totalSellingExcludingGst)]]});\n autoTable(pdf,{startY:(pdf as any).lastAutoTable.finalY+6,theme:'plain',styles:{fontSize:9,cellPadding:2},columnStyles:{1:{halign:'right'}},body:[['IPO total before tax',right(s.totalSellingExcludingGst)],['IPO tax (separate reconciliation)',right(s.totalGst)],['IPO payable',right(s.totalPayable)]]});\n pdf.setFontSize(8);pdf.text(pdf.splitTextToSize('PT selling values are locked to agreed capacity and the saved proportional allocation. Actual usage affects actual costs and markup. Final invoice panel allocation may differ after verified IRR review, while the agreed total stays unchanged before authorized cable adjustments. BESS Total is a subtotal, not an additional phase. EPC absorbs rounding only. Historical registration does not record an invoice, dispatch or job closure.',180),14,(pdf as any).lastAutoTable.finalY+8);\n if(kind==='ipo')pdf.deletePage(2);else if(kind==='pt')pdf.deletePage(1);\n drawReportFooter(pdf,reference);pdf.setProperties({title:reference,author:'Power Zone Engineering & Services'});return Buffer.from(pdf.output('arraybuffer'));\n}\n","server/ubl/ipo-sample.ts":"import {Decimal} from 'decimal.js';\nimport {HttpError} from '../http/errors.js';\nconst D=(v:any)=>new Decimal(v);\nconst rounded=(v:Decimal)=>v.toDecimalPlaces(2,Decimal.ROUND_HALF_UP);\nconst fixed=(v:Decimal)=>rounded(v).toFixed(2);\nconst names=['Solar Panels','Structure','Inverter','Batteries','BMS','EPC'];\nexport function ublIpoSample(site:any){\n if(site.status!=='Active'||!site.baseline)throw new HttpError(422,'An active PO and agreed baseline are required.');\n const b=site.baseline, costs=names.map(()=>D(0));\n for(const i of b.items){const phase=i.item==='Solar panels'?0:i.item==='Elevated structure'?1:/^HYB-/.test(i.item)?2:/battery$/i.test(i.item)?3:/^HV BMS$/.test(i.item)?4:5;costs[phase]=costs[phase].add(i.total_ex_gst);}\n const cost=costs.reduce((v,c)=>v.add(c),D(0));\n if(!cost.eq(b.budgetedCost))throw new HttpError(422,'Saved item costs do not reconcile.');\n const total=rounded(D(b.sellingIncludingGst)),panel=rounded(D(b.commercialEvidence.panelSellingExcludingGst)),panelTax=rounded(panel.mul('0.10'));\n const installationPayable=total.sub(panel).sub(panelTax),installationSelling=rounded(installationPayable.div('1.18')),installationTax=installationPayable.sub(installationSelling);\n const remainingCost=cost.sub(costs[0]);if(!remainingCost.gt(0))throw new HttpError(422,'Installation phase costs are unavailable.');\n let allocatedSelling=D(0),allocatedTax=D(0);\n const phases=names.map((name,index)=>{\n  const selling=index===0?panel:index===5?installationSelling.sub(allocatedSelling):rounded(installationSelling.mul(costs[index]).div(remainingCost));\n  const tax=index===0?panelTax:index===5?installationTax.sub(allocatedTax):rounded(selling.mul('0.18'));\n  if(index>0){allocatedSelling=allocatedSelling.add(selling);allocatedTax=allocatedTax.add(tax);}\n  return {name,budgetedCost:fixed(costs[index]),sellingExcludingGst:fixed(selling),gst:fixed(tax),payable:fixed(selling.add(tax)),markup:fixed(selling.sub(costs[index]))};\n });\n if(!phases.reduce((v,p)=>v.add(p.payable),D(0)).eq(total))throw new HttpError(422,'PT phases do not reconcile with the approved PO.');\n const net=panel.add(installationSelling);\n return {version:1,customerMaster:site.customerMaster??null,purpose:site.documentStatus??'Review sample only - not issued or sent to Accounts',documentStatus:site.documentStatus??'Review sample',agreedWatts:site.agreedWatts??null,panelSellingRate:site.panelSellingRate??null,siteName:site.site_name,branchCode:site.branch_code,region:site.region,mainCity:site.main_city,legacyIpoNumber:site.legacy_ipo_number,poNumber:site.po_number,poIssuedDate:site.po_issued_date,configuration:site.configuration_id,pricingStage:site.pricing_stage,customer:'United Bank Limited (UBL)',billing:[{name:'Solar Panels',sellingExcludingGst:fixed(panel),gstRate:'10%',gst:fixed(panelTax),payable:fixed(panel.add(panelTax))},{name:'Installations',sellingExcludingGst:fixed(installationSelling),gstRate:'18%',gst:fixed(installationTax),payable:fixed(installationPayable)}],phases,totalSellingExcludingGst:fixed(net),totalGst:fixed(total.sub(net)),totalPayable:fixed(total),budgetedCost:fixed(cost),markupAmount:fixed(net.sub(cost)),markupPercent:net.sub(cost).div(cost).mul(100).toFixed(2),installationMarkupPercent:installationSelling.sub(remainingCost).div(remainingCost).mul(100).toFixed(6),allocationPolicy:'Panel selling amount is locked to the agreed pricing stage. Installation selling is allocated in proportion to saved non-panel phase costs, using one common markup percentage. EPC absorbs rounding only. GST-inclusive total remains exactly the approved PO amount.',reviewNotes:b.reviewNotes};\n}\n","server/boq/report.ts":"import { displayUnit } from \"./unit.js\";\nimport {\n  drawReportLogo,\n  drawReportFooter,\n  reportBottomMargin,\n} from \"../reports/branding.js\";\nimport type { BoqSnapshot } from \"./engine.js\";\nimport { jsPDF } from \"jspdf\";\nimport { autoTable } from \"jspdf-autotable\";\n\nconst money = (v: string | number, d = 0) => v == null ? \"Restricted\" :\n  new Intl.NumberFormat(\"en-PK\", {\n    minimumFractionDigits: d,\n    maximumFractionDigits: d,\n  }).format(Number(v));\n// Standard PDF fonts cover Latin-1; normalise engineering glyphs explicitly.\nconst label = (v: string) =>\n  v\n    .replaceAll(\"×\", \"x\")\n    .replace(/[–—]/g, \"-\")\n    .replace(/[^\\n\\x20-\\x7e\\xa0-\\xff]/g, \"\");\n\nexport function buildCostingPdf(\n  s: BoqSnapshot,\n  number?: string,\n  createdAt?: string,\n) {\n  const pdf = new jsPDF({ unit: \"mm\", format: \"a4\", compress: true });\n  const width = pdf.internal.pageSize.getWidth(),\n    margin = 14;\n  const title = `${number || \"Costing preview\"}${(s as any).costVisibility ? \" - Excluding BESS costs\" : \"\"}`;\n  pdf.setProperties({\n    title: `${title} - ${s.survey.siteName}`,\n    author: \"Power Zone Engineering & Services\",\n    subject: \"Internal project costing\",\n  });\n  pdf.setFont(\"helvetica\", \"bold\");\n  pdf.setFontSize(19);\n  pdf.setTextColor(57, 50, 83);\n  drawReportLogo(pdf);\n  pdf.setFontSize(9);\n  pdf.setFont(\"helvetica\", \"normal\");\n  pdf.text(\"ENGINEERING & SERVICES\", 60, 19);\n  pdf.text(\"INTERNAL PROJECT COSTING\", 60, 25);\n  pdf.setTextColor(35, 35, 40);\n  pdf.setFontSize(13);\n  pdf.setFont(\"helvetica\", \"bold\");\n  pdf.text(label(title), margin, 40);\n  pdf.setFont(\"helvetica\", \"normal\");\n  pdf.setFontSize(9);\n  const metadata = [\n    `Customer: ${s.customer.name}`,\n    `Site: ${s.survey.siteName} | Code: ${s.survey.siteCode} | Location: ${s.survey.location}`,\n    s.survey.family === \"direct-product\" ? \"Direct Product Sale\" : `${s.survey.family === \"bess-only\" ? \"BESS Only (UPS with Installation)\" : `PV: ${money(s.engineering.pvKwp,3)} kWp`} | Inverter: ${s.survey.inverter} | Battery: ${s.survey.batteryKwh} kWh`,\n    ...(s.generalAllowances\n      ? [\n          `Source: General quotation without survey | Allowances: ${s.generalAllowances.version}`,\n        ]\n      : []),\n    `Prepared by: ${s.survey.preparedBy}${createdAt ? \" | Saved: \" + new Date(createdAt).toISOString().slice(0, 10) : \"\"}`,\n    number\n      ? \"Saved BOQ costing. This report uses the preserved snapshot.\"\n      : \"DRAFT PREVIEW - No BOQ number has been issued.\",\n  ];\n  let y = 47;\n  for (const line of metadata) {\n    const lines = pdf.splitTextToSize(label(line), width - margin * 2);\n    pdf.text(lines, margin, y);\n    y += lines.length * 4.5 + 1;\n  }\n  const section = (\n    heading: string,\n    head: string[],\n    body: string[][],\n    detail = false,\n  ) => {\n    if (y > 245) {\n      pdf.addPage();\n      y = 20;\n    }\n    pdf.setFont(\"helvetica\", \"bold\");\n    pdf.setFontSize(11);\n    pdf.text(heading, margin, y);\n    y += 5;\n    autoTable(pdf, {\n      startY: y,\n      margin: {\n        left: margin,\n        right: margin,\n        top: 18,\n        bottom: reportBottomMargin,\n      },\n      head: [head],\n      body,\n      theme: \"striped\",\n      styles: {\n        font: \"helvetica\",\n        fontSize: detail ? 8 : 9,\n        cellPadding: 2.5,\n        overflow: \"linebreak\",\n        lineColor: [231, 231, 239],\n        lineWidth: 0.1,\n      },\n      headStyles: {\n        fillColor: [57, 50, 83],\n        textColor: 255,\n        fontStyle: \"bold\",\n      },\n      alternateRowStyles: { fillColor: [247, 246, 251] },\n      columnStyles: detail\n        ? {\n            0: { cellWidth: 32 },\n            1: { cellWidth: 21 },\n            2: { cellWidth: 52 },\n            3: { cellWidth: 16, halign: \"right\" },\n            4: { cellWidth: 13 },\n            5: { cellWidth: 22, halign: \"right\" },\n            6: { cellWidth: 26, halign: \"right\" },\n          }\n        : { 1: { halign: \"right\" }, 2: { halign: \"right\" } },\n      rowPageBreak: \"avoid\",\n      showHead: \"everyPage\",\n      didParseCell: (data) => {\n        if (\n          !detail &&\n          data.section === \"body\" &&\n          Array.isArray(data.row.raw) &&\n          data.row.raw[0] === \"TOTAL PROJECT COST\"\n        ) {\n          data.cell.styles.fontStyle = \"bold\";\n          data.cell.styles.fillColor = [237, 234, 250];\n        }\n      },\n    });\n    y =\n      (pdf as jsPDF & { lastAutoTable: { finalY: number } }).lastAutoTable\n        .finalY + 12;\n  };\n  section(\n    \"Project Costing Summary\",\n    [\"Item\", \"Budgeted Cost (PKR)\", \"Cost/W\"],\n    [\n      ...s.summary.map((x) => [x.name, money(x.cost), s.survey.family !== \"solar-hybrid\" && s.survey.family ? \"-\" : money(x.perWatt, 2)]),\n      [(s as any).costVisibility ? \"PROJECT COST EXCLUDING BESS\" : \"TOTAL PROJECT COST\", money(s.total), s.survey.family !== \"solar-hybrid\" && s.survey.family ? \"-\" : money(s.perWatt, 2)],\n    ],\n  );\n  if (s.epc.length) section(\n    \"EPC Costing Breakup\",\n    [\"Item\", \"Budgeted Cost (PKR)\", \"Cost/W\"],\n    s.epc.map((x) => [x.name, money(x.cost), s.survey.family !== \"solar-hybrid\" && s.survey.family ? \"-\" : money(x.perWatt, 2)]),\n  );\n  if (s.warnings.length)\n    section(\n      \"Rate review notices\",\n      [\"Review note\"],\n      s.warnings.map((w) => [label(w)]),\n    );\n  // Details start on a fresh page so executives see the two summaries first.\n  pdf.addPage();\n  y = 20;\n  section(\n    \"Project Costing Detailed Breakup\",\n    [\n      \"Item / Description\",\n      \"Brand\",\n      \"Detailed Specification\",\n      \"Qty\",\n      \"UOM\",\n      \"Unit Rate (PKR)\",\n      \"Total Cost (PKR)\",\n    ],\n    s.lines.map((l) => [\n      label(l.itemId ? `${l.itemId}\\n${l.description}` : l.description),\n      label([l.brand || \"-\", ...l.brandAlternatives].join(\"\\n\")),\n      label(l.specification || \"-\"),\n      money(l.qty, Number(l.qty) % 1 ? 2 : 0),\n      label(displayUnit(l.unit,l.qty)),\n      money(l.rate, Number(l.rate) % 1 ? 4 : 0),\n      money(l.total),\n    ]),\n    true,\n  );\n  drawReportFooter(\n    pdf,\n    label(`${title} | ${s.survey.siteCode} | Internal costing`),\n  );\n  return pdf;\n}\n","server/operations/report.ts":"import { quotationTypeLabel } from \"../orders/sale-type.js\";\nimport { jsPDF } from \"jspdf\";\nimport { autoTable } from \"jspdf-autotable\";\nimport {\n  drawReportLogo,\n  drawReportFooter,\n  reportBottomMargin,\n} from \"../reports/branding.js\";\nconst clean = (v: unknown) =>\n  String(v ?? \"\")\n    .replaceAll(\"²\", \"2\")\n    .replaceAll(\"×\", \"x\")\n    .replace(/[–—]/g, \"-\")\n    .replace(/[^\\n\\x20-\\x7e\\xa0-\\xff]/g, \"\");\nexport function buildOperationsPdf(row: any) {\n  const s = row.snapshot,\n    pdf = new jsPDF({ unit: \"mm\", format: \"a4\", compress: true });\n  drawReportLogo(pdf);\n  pdf.setFontSize(12);\n  pdf.text(\n    s.destination === \"Store\"\n      ? \"BOQ ISSUANCE TO STORE\"\n      : \"BOQ ISSUANCE TO OPERATIONS\",\n    14,\n    38,\n  );\n  pdf.setFontSize(8);\n  pdf.text(\"POWER ZONE ENGINEERING & SERVICES (PVT) LIMITED\", 14, 44);\n  autoTable(pdf, {\n    startY: 50,\n    theme: \"grid\",\n    styles: { fontSize: 8, cellPadding: 2 },\n    body: [\n      [\"Issuance\", row.number, \"IPO\", s.ipoNumber],\n      [\"Customer\", clean(s.customer.name), \"Quotation\", s.quotationNumber],\n      [\n        \"Quotation type\",\n        clean(quotationTypeLabel(row.quotationType ?? s)),\n        \"\",\n        \"\",\n      ],\n      [\n        \"Site\",\n        clean(`${s.siteName} / ${s.siteCode}`),\n        \"Approved BOQ\",\n        s.boqNumber,\n      ],\n      [\n        \"Customer contact\",\n        clean(`${s.contactPerson} / ${s.phone}`),\n        \"Site contact\",\n        clean(`${s.siteContact} / ${s.sitePhone}`),\n      ],\n      [\n        \"Delivery address\",\n        clean(s.deliveryAddress),\n        \"Customer PO\",\n        clean(s.customerPo),\n      ],\n      ...(s.destination === \"Store\"\n        ? [\n            [\n              \"Delivery date / time\",\n              clean(\n                `${s.deliveryDate} / ${s.deliveryTime || \"To be arranged\"}`,\n              ),\n              \"Operations reference\",\n              s.operationsIssuanceNumber,\n            ],\n          ]\n        : []),\n      [\n        \"Issued by\",\n        clean(s.issuedBy),\n        \"Issued on\",\n        new Date(row.created_at).toLocaleDateString(\"en-GB\", {\n          timeZone: \"Asia/Karachi\",\n        }),\n      ],\n    ],\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 6,\n    theme: \"grid\",\n    margin: { bottom: reportBottomMargin },\n    headStyles: { fillColor: [61, 63, 146] },\n    styles: { fontSize: 8, cellPadding: 2 },\n    columnStyles: {\n      0: { cellWidth: 9, halign: \"center\" },\n      2: { cellWidth: 15, halign: \"center\" },\n      3: { cellWidth: 15, halign: \"center\" },\n    },\n    head: [[\"No.\", \"Required item / specification / brand\", \"Qty\", \"Unit\"]],\n    body: s.items.map((l: any, i: number) => [\n      String(i + 1),\n      clean(\n        [\n          l.description,\n          l.specification || \"Specification: Need to enter\",\n          l.brand === \"Any of the Above\"\n            ? l.brandAlternatives?.join(\" / \")\n            : l.brand,\n        ]\n          .filter(Boolean)\n          .join(\"\\n\"),\n      ),\n      l.qty,\n      l.unit,\n    ]),\n  });\n  let y = (pdf as any).lastAutoTable.finalY + 7;\n  const note = pdf.splitTextToSize(clean(s.notes), 180);\n  if (y + note.length * 4 > 265) {\n    pdf.addPage();\n    y = 20;\n  }\n  pdf.setFontSize(8);\n  if (s.notes) pdf.text(note, 14, y);\n  drawReportFooter(pdf, row.number);\n  return Buffer.from(pdf.output(\"arraybuffer\"));\n}\n","server/reports/branding.ts":"import type { jsPDF } from \"jspdf\";\nimport { logo, footer } from \"./brand-assets.js\";\n\nexport const reportBottomMargin = 32;\nexport function drawReportLogo(pdf: jsPDF) {\n  pdf.addImage(logo, \"PNG\", 14, 9, 38, 38 * 2384 / 3786, \"power-zone-logo\", \"FAST\");\n  pdf.setFont(\"helvetica\", \"bold\");\n  pdf.setFontSize(8);\n  pdf.setTextColor(90, 90, 100);\n  pdf.text(\"Security Level: Confidential\", 196, 12, { align: \"right\" });\n}\nexport function drawReportFooter(pdf: jsPDF, reference: string) {\n  const pages = pdf.getNumberOfPages();\n  for (let page = 1; page <= pages; page++) {\n    pdf.setPage(page);\n    pdf.setFont(\"helvetica\", \"normal\");\n    pdf.setFontSize(7);\n    pdf.setTextColor(110, 110, 120);\n    pdf.text(reference, 14, 269);\n    pdf.text(`Page ${page} of ${pages}`, 196, 269, { align: \"right\" });\n    pdf.addImage(footer, \"PNG\", 10, 275, 190, 190 * 218 / 2054, \"power-zone-footer\", \"FAST\");\n  }\n}\n","server/reports/brand-assets.ts":"// Original owner-supplied brand assets, embedded for compiled server PDF generation.\nexport const logo = \"data:image/png;base64,\";\nexport const footer = \"data:image/png;base64,\";\n"}}$format$::jsonb);
